        Calls.Add(new SupplierCall(sku, quantity));
        return _placeOrderResult;
    }
}

internal sealed class SupplierCall
{
    public SupplierCall(string sku, int quantity)
    {
        Sku = sku;
        Quantity = quantity;
    }

    public string Sku { get; }
    public int Quantity { get; }
}

